// eslint-config-next@16 ships native flat configs; spread them directly.
import next from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";

const eslintConfig = [
  ...next,
  ...nextTs,
  {
    // shared/contracts/gen is generated by `buf generate`; public/mfe holds the
    // built (minified) element-remote bundles — neither is hand-written, don't lint.
    ignores: [".next/**", "node_modules/**", "dist/**", "public/mfe/**", "shared/contracts/gen/**"],
  },
  {
    // All env access is centralised in config.ts; everything else imports the
    // typed `config` object instead of reaching into process.env. Tests exercise
    // env-driven config paths, so they may set process.env; the mfe/build.mjs
    // esbuild `define` names process.env.NODE_ENV as a replace token, not a read.
    ignores: ["config.ts", "**/*.test.ts", "mfe/build.mjs"],
    rules: {
      "no-restricted-properties": [
        "error",
        {
          object: "process",
          property: "env",
          message: "Read env through the typed `config` object (config.ts), not process.env.",
        },
      ],
    },
  },
  {
    // The cabinet had accumulated 386 arbitrary Tailwind values — 24 distinct font
    // sizes and 10 radii against the 8 and 5 the design system defines. That happened
    // because nothing stopped it, not because anyone chose it, so the guard is a lint
    // rule rather than a convention.
    //
    // Only brackets opening on a digit or `#` are caught: those are the hardcoded
    // sizes and colours. `calc()`, `var()` and `env()` brackets are how the shell
    // contract and device insets are expressed and stay legal, as does the
    // `grid-cols-(--name)` form for a fixed track with no step on the scale.
    // Bare viewport units are exempt for the same reason — `min-h-[60vh]` sizes
    // against the viewport, which no spacing step can express.
    files: ["**/*.ts", "**/*.tsx"],
    rules: {
      "no-restricted-syntax": [
        "error",
        {
          selector: "Literal[value=/-\\[(?!\\d+(?:\\.\\d+)?(?:d|s|l)?v[hw]\\])(?:#|\\d)/]",
          message: "Arbitrary Tailwind value — use a scale step, or a CSS custom property for a genuine one-off.",
        },
        {
          selector: "TemplateElement[value.raw=/-\\[(?!\\d+(?:\\.\\d+)?(?:d|s|l)?v[hw]\\])(?:#|\\d)/]",
          message: "Arbitrary Tailwind value — use a scale step, or a CSS custom property for a genuine one-off.",
        },
      ],
    },
  },
  {
    // `motion.*` carries motion's whole feature set — layout projection and drag
    // included — and a single use anywhere pulls it into the shared chunk of every
    // route (~15 KB gz). Everything outside the panel animates opacity and
    // transform only, which `m` under `MotionFeatures` covers with `domAnimation`.
    // `Panel` animates its own size and needs projection, so its slice is the one
    // place `motion` is allowed. See shared/ui/motion/features.tsx.
    files: ["**/*.ts", "**/*.tsx"],
    ignores: ["shared/ui/motion-panel/**"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: ["motion/react", "framer-motion"].map((name) => ({
            name,
            importNames: ["motion"],
            message:
              "`motion` loads layout projection and drag on every route (~15 KB gz). Use `m` from `motion/react-m` under `MotionFeatures` (@/shared/ui/motion), or `Panel` (@/shared/ui/motion-panel) for a size-animating panel.",
          })),
        },
      ],
    },
  },
];

export default eslintConfig;
